window.__PAGES=window.__PAGES||{};window.__PAGES["pages/settings-organization-roles.html"]="<!-- Settings: Organisasi — Role & Permission -->\n<style>\n.st-role-card{background:var(--card);border:1px solid var(--border);border-radius:var(--radius);padding:16px;margin-bottom:10px}\n.st-role-head{display:flex;align-items:center;justify-content:space-between}\n.st-role-name{font-size:15px;font-weight:600}\n.st-perm-list{display:flex;gap:6px;flex-wrap:wrap;margin-top:8px}\n.st-perm-chip{display:inline-block;padding:2px 8px;border-radius:10px;font-size:11px;font-weight:600;background:#f3f4f6;color:#374151}\n.st-perm-chip.all{background:#fef3c7;color:#b45309}\n.st-check-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px}\n.st-check-grid label{display:flex;align-items:center;gap:6px;font-size:13px;cursor:pointer}\n.st-check-grid input[type=checkbox]{accent-color:var(--accent)}\n</style>\n\n<div class=\"settings-layout\">\n  <aside class=\"settings-sidenav\" id=\"stNav\"></aside>\n  <div class=\"settings-body\">\n    <div style=\"display:flex;align-items:center;justify-content:space-between;margin-bottom:16px\">\n      <div><h2 style=\"margin-bottom:4px\">Role & Permission</h2><p style=\"font-size:13px;color:var(--muted)\">Kelola role dan hak akses anggota.</p></div>\n      <button class=\"btn primary\" onclick=\"openAddRole()\">+ Tambah Role</button>\n    </div>\n    <div id=\"rolesList\"></div>\n\n    <!-- Add/Edit role modal -->\n    <div class=\"modal-overlay\" id=\"modalRole\">\n      <div class=\"modal\">\n        <h3 id=\"roleModalTitle\">Tambah Role</h3>\n        <label>Nama Role<input type=\"text\" id=\"roleName\"></label>\n        <div style=\"margin-bottom:8px\"><strong style=\"font-size:13px\">Permission:</strong></div>\n        <div class=\"st-check-grid\" id=\"permChecks\"></div>\n        <div class=\"modal-actions\"><button class=\"btn\" onclick=\"document.getElementById('modalRole').classList.remove('open')\">Batal</button><button class=\"btn primary\" onclick=\"saveRole()\">Simpan</button></div>\n      </div>\n    </div>\n  </div>\n</div>\n\n<script>\n(function(){\n  document.getElementById('stNav').innerHTML=renderSettingsNav('organization-roles');\n\n  const ALL_PERMS=['all','reply','assign','view_all','view_assigned','manage_members','manage_settings','export_data'];\n  const PERM_LABELS={all:'Semua Akses',reply:'Balas Pesan',assign:'Tugaskan',view_all:'Lihat Semua',view_assigned:'Lihat Ditugaskan',manage_members:'Kelola Anggota',manage_settings:'Kelola Pengaturan',export_data:'Export Data'};\n  let editingRoleId=null;\n\n  function render(){\n    const el=document.getElementById('rolesList');\n    if(!DB.settings.roles.length){el.innerHTML='<p style=\"color:var(--muted);padding:20px\">Belum ada role.</p>';return}\n    el.innerHTML=DB.settings.roles.map(r=>`\n      <div class=\"st-role-card\">\n        <div class=\"st-role-head\">\n          <span class=\"st-role-name\">${r.name}</span>\n          <button class=\"btn\" style=\"font-size:11px;padding:3px 10px\" onclick=\"openEditRole('${r.id}')\">✏ Edit</button>\n        </div>\n        <div class=\"st-perm-list\">${r.perms.map(p=>`<span class=\"st-perm-chip ${p==='all'?'all':''}\">${PERM_LABELS[p]||p}</span>`).join('')}</div>\n      </div>\n    `).join('');\n  }\n  render();\n\n  function renderPermChecks(selected){\n    return ALL_PERMS.map(p=>`<label><input type=\"checkbox\" value=\"${p}\" ${selected.includes(p)?'checked':''}> ${PERM_LABELS[p]}</label>`).join('');\n  }\n\n  window.openAddRole=function(){\n    editingRoleId=null;\n    document.getElementById('roleModalTitle').textContent='Tambah Role';\n    document.getElementById('roleName').value='';\n    document.getElementById('permChecks').innerHTML=renderPermChecks([]);\n    document.getElementById('modalRole').classList.add('open');\n  };\n\n  window.openEditRole=function(id){\n    editingRoleId=id;\n    const role=DB.settings.roles.find(x=>x.id===id);\n    document.getElementById('roleModalTitle').textContent='Edit Role';\n    document.getElementById('roleName').value=role.name;\n    document.getElementById('permChecks').innerHTML=renderPermChecks(role.perms);\n    document.getElementById('modalRole').classList.add('open');\n  };\n\n  window.saveRole=function(){\n    const name=document.getElementById('roleName').value.trim();\n    if(!name){showToast('Nama role wajib diisi');return}\n    const perms=[...document.querySelectorAll('#permChecks input:checked')].map(c=>c.value);\n    if(editingRoleId){\n      const role=DB.settings.roles.find(x=>x.id===editingRoleId);\n      role.name=name;role.perms=perms;\n    }else{\n      DB.settings.roles.push({id:genId('r'),name,perms});\n    }\n    saveStore();render();\n    document.getElementById('modalRole').classList.remove('open');\n    showToast(editingRoleId?'Role diperbarui':'Role ditambahkan');\n  };\n})();\n</script>\n";
